// Uses the installed browser only. No external connections or dependencies.
const fs=require('node:fs');
const {pathToFileURL}=require('node:url');
(async()=>{
 const tabs=await (await fetch('http://127.0.0.1:9224/json')).json();
 const ws=new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl);
 await new Promise(r=>ws.onopen=r);
 let seq=0;const pending=new Map(); const errors=[];
 ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id){pending.get(m.id)?.(m);pending.delete(m.id)}if(m.method==='Runtime.exceptionThrown')errors.push(m.params.exceptionDetails.text)};
 const call=(method,params={})=>new Promise((resolve,reject)=>{const id=++seq;pending.set(id,m=>m.error?reject(Error(JSON.stringify(m.error))):resolve(m.result));ws.send(JSON.stringify({id,method,params}))});
 const run=async expression=>{const r=await call('Runtime.evaluate',{expression,returnByValue:true});if(r.exceptionDetails)throw Error(JSON.stringify(r.exceptionDetails));return r.result.value};
 const check=async(label,expression)=>{if(!await run(expression))throw Error(label);console.log('PASS '+label)};
 await call('Runtime.enable');
 await call('Emulation.setDeviceMetricsOverride',{width:390,height:844,deviceScaleFactor:1,mobile:true});
 await call('Page.navigate',{url:pathToFileURL(require('node:path').resolve('index.html')).href});
 for(let i=0;i<100;i++){if(await run("!!document.querySelector('#start')"))break;await new Promise(r=>setTimeout(r,50))}
 await run("document.querySelector('#start').click();document.querySelector('form').requestSubmit()");
 await check('required field blocks progression',"step===0&&!!document.querySelector('#error').textContent");
 await run("document.querySelector('input').click();document.querySelector('form').requestSubmit();document.querySelector('input[value=\"网站原型\"]').click();document.querySelector('input[value=\"表格分析\"]').click()");
 await check('both conditional branches available',"ids().join(',')==='role,topics,code,problem,time,note'");
 await run("document.querySelector('form').requestSubmit();document.querySelector('input').click();document.querySelector('form').requestSubmit();document.querySelector('#text').value='合成汇总问题';document.querySelector('#text').dispatchEvent(new Event('input'));document.querySelector('#back').click();document.querySelector('#back').click();document.querySelector('input[value=\"暂时没有明确方向\"]').click()");
 await check('exclusive option clears dependent data',"answers.topics.length===1&&answers.code===''&&answers.problem===''&&ids().length===4");
 await run("document.querySelector('form').requestSubmit();document.querySelector('input').click();document.querySelector('form').requestSubmit();document.querySelector('form').requestSubmit()");
 await check('optional blank completes with unscored result',"screen==='result'&&document.querySelector('#download')&&document.body.innerText.includes('未填写（选填）')&&!document.body.innerText.includes('undefined')");
 await check('mobile has no horizontal overflow',"document.documentElement.scrollWidth<=390");
 await call('Page.setDownloadBehavior',{behavior:'allow',downloadPath:require('node:path').resolve('demo-downloads')});
 await run("document.querySelector('#download').click()");
 for(let i=0;i<100&&!fs.existsSync('demo-downloads/我的培训需求-演示.txt');i++)await new Promise(r=>setTimeout(r,50));
 if(!fs.readFileSync('demo-downloads/我的培训需求-演示.txt','utf8').includes('暂时没有明确方向'))throw Error('Download missing');console.log('PASS actual summary download');
 await run("document.querySelector('#edit').click()");
 await check('back retains selected answer',"document.querySelector('input').checked");
 await call('Page.reload');
 for(let i=0;i<100;i++){if(await run("!!document.querySelector('#start')"))break;await new Promise(r=>setTimeout(r,50))}
 await check('reload recovers session draft',"answers.role==='办公协作'&&answers.topics[0]==='暂时没有明确方向'");
 await run("document.querySelector('#example').click()");
 await check('sample form fits mobile',"document.documentElement.scrollWidth<=390");
 await call('Page.captureScreenshot',{format:'png'}).then(r=>fs.writeFileSync('preview-mobile.png',Buffer.from(r.data,'base64')));
 await run("for(let i=0;i<6;i++)document.querySelector('form').requestSubmit()");
 await check('full conditional flow produces corresponding summary',"screen==='result'&&document.body.innerText.includes('没写过')&&document.body.innerText.includes('合成销售表')&&summaryRows().length===6");
 await run("document.querySelector('#edit').click()");
 await check('heading receives keyboard focus after navigation',"document.activeElement.tagName==='H2'");
 await run("screen='result';render();document.querySelector('#clear').click()");
 await check('clear resets answers and session draft',"answers.role===''&&answers.topics.length===0&&sessionStorage.getItem('training-demo-v1')===null");
 if(errors.length)throw Error(errors.join(';'));
 console.log('PASS no browser runtime exceptions');
 await call('Browser.close');ws.close();
})().catch(e=>{console.error(e);process.exit(1)});

